351	// Close flushes and closes the journal. It is safe to call more than once.
352	func (j *SessionJournal) Close() error {
353		j.mu.Lock()
354		defer j.mu.Unlock()
355		if j.closed {
356			return nil
357		}
358		j.closed = true
359		flushErr := j.writer.Flush()
360		closeErr := j.file.Close()
361		return errors.Join(flushErr, closeErr)
362	}
