364	func (j *SessionJournal) appendRecord(record SessionRecord) error {
365		line, err := json.Marshal(record)
366		if err != nil {
367			return fmt.Errorf("编码会话记录失败: %w", err)
368		}
369		j.mu.Lock()
370		defer j.mu.Unlock()
371		if j.closed {
372			return fmt.Errorf("会话 %s 已关闭", j.id)
373		}
374		if _, err := j.writer.Write(line); err != nil {
375			return fmt.Errorf("写入会话 %s 失败: %w", j.id, err)
376		}
377		if err := j.writer.WriteByte('\n'); err != nil {
378			return fmt.Errorf("写入会话 %s 失败: %w", j.id, err)
379		}
380		if err := j.writer.Flush(); err != nil {
381			return fmt.Errorf("刷新会话 %s 失败: %w", j.id, err)
382		}
383		return nil
384	}
