398	func validateSessionRecord(record SessionRecord) error {
399		if record.Timestamp.IsZero() {
400			return fmt.Errorf("会话记录缺少 timestamp")
401		}
402		switch record.Type {
403		case RecordMessage:
404			if record.Message == nil {
405				return fmt.Errorf("message 记录缺少 message")
406			}
407		case RecordSnapshot:
408			if record.Messages == nil {
409				return fmt.Errorf("snapshot 记录缺少 messages")
410			}
411		default:
412			return fmt.Errorf("未知会话记录类型: %s", record.Type)
413		}
414		return nil
415	}
