417	func validMessagePrefix(messages []timedMessage) (int, string) {
418		pending := make([]string, 0)
419		groupStart := -1
420		completed := 0
421		for i, item := range messages {
422			message := item.message
423			switch message.Role {
424			case "user":
425				if len(pending) > completed {
426					return groupStart, "工具调用缺少结果，已截断到最长合法消息前缀"
427				}
428			case "assistant":
429				if len(pending) > completed {
430					return groupStart, "工具调用结果不完整，已截断到最长合法消息前缀"
431				}
432				pending = pending[:0]
433				completed = 0
434				groupStart = -1
435				if len(message.ToolCalls) > 0 {
436					groupStart = i
437					seen := make(map[string]struct{}, len(message.ToolCalls))
438					for _, call := range message.ToolCalls {
439						if strings.TrimSpace(call.ID) == "" {
440							return i, "工具调用缺少 ID，已截断到最长合法消息前缀"
441						}
442						if _, exists := seen[call.ID]; exists {
443							return i, "工具调用 ID 重复，已截断到最长合法消息前缀"
444						}
445						seen[call.ID] = struct{}{}
446						pending = append(pending, call.ID)
447					}
448				}
449			case "tool":
450				if message.ToolResult == nil || groupStart < 0 || completed >= len(pending) {
451					return i, "存在孤立工具结果，已截断到最长合法消息前缀"
452				}
453				if message.ToolResult.ToolUseID != pending[completed] {
454					return groupStart, "工具结果 ID 或顺序不匹配，已截断到最长合法消息前缀"
455				}
456				completed++
457			default:
458				return i, fmt.Sprintf("未知消息角色 %q，已截断到最长合法消息前缀", message.Role)
459			}
460		}
461		if len(pending) > completed {
462			return groupStart, "会话末尾工具调用缺少结果，已截断到最长合法消息前缀"
463		}
464		return len(messages), ""
465	}
