467	func sessionTitle(messages []llm.Message, fallback string) string {
468		for _, message := range messages {
469			if message.Role != "user" {
470				continue
471			}
472			content := strings.TrimSpace(strings.ReplaceAll(message.Content, "\r\n", "\n"))
473			firstLine := strings.SplitN(content, "\n", 2)[0]
474			title := strings.Join(strings.Fields(firstLine), " ")
475			if title == "" {
476				continue
477			}
478			runes := []rune(title)
479			if len(runes) > 60 {
480				title = string(runes[:60])
481			}
482			return title
483		}
484		return fallback
485	}
