97	// Apply validates local storage invariants, writes notes, then rebuilds indexes.
98	func (s *NoteStore) Apply(mutations []NoteMutation) error {
99		if !s.Enabled {
100			return nil
101		}
102		for _, mutation := range mutations {
103			switch mutation.Operation {
104			case MutationSkip:
105				continue
106			case MutationCreate:
107				changed, scope, err := s.create(mutation.Note)
108				if err != nil {
109					return err
110				}
111				if changed {
112					if err := s.RebuildIndex(scope); err != nil {
113						return err
114					}
115				}
116			case MutationUpdate:
117				changed, scope, err := s.update(mutation.TargetID, mutation.Note)
118				if err != nil {
119					return err
120				}
121				if changed {
122					if err := s.RebuildIndex(scope); err != nil {
123						return err
124					}
125				}
126			default:
127				return fmt.Errorf("未知记忆操作: %s", mutation.Operation)
128			}
129		}
130		return nil
131	}
