133	// RebuildIndex regenerates one scope's bounded INDEX.md from actual notes.
134	func (s *NoteStore) RebuildIndex(scope Scope) error {
135		root, err := s.rootFor(scope)
136		if err != nil {
137			return err
138		}
139		notes, err := s.readAllNotes(scope)
140		if err != nil {
141			return err
142		}
143		sort.Slice(notes, func(i, j int) bool {
144			if notes[i].UpdatedAt.Equal(notes[j].UpdatedAt) {
145				return notes[i].ID < notes[j].ID
146			}
147			return notes[i].UpdatedAt.After(notes[j].UpdatedAt)
148		})
149	
150		lines := []string{"# OneCode Memory Index", ""}
151		for _, note := range notes {
152			line := fmt.Sprintf("- [%s](notes/%s.md) [%s] - %s",
153				indexText(note.Title), note.ID, note.Category, indexText(note.Summary))
154			lines = append(lines, line)
155		}
156		content := boundText(strings.Join(lines, "\n")+"\n", indexMaxLines, indexMaxBytes)
157		if err := os.MkdirAll(root, 0o755); err != nil {
158			return fmt.Errorf("创建记忆目录失败: %w", err)
159		}
160		if err := s.writeFile(filepath.Join(root, "INDEX.md"), []byte(content), 0o600); err != nil {
161			return fmt.Errorf("更新 %s 记忆索引失败: %w", scope, err)
162		}
163		return nil
164	}
165	
166	// LoadIndexes returns bounded user and project indexes for one model request.
167	func (s *NoteStore) LoadIndexes() (string, error) {
168		if !s.Enabled {
169			return "", nil
170		}
171		userContent, userErr := readOptionalFile(filepath.Join(s.UserRoot, "INDEX.md"))
172		projectContent, projectErr := readOptionalFile(filepath.Join(s.ProjectRoot, "INDEX.md"))
173		if userErr != nil || projectErr != nil {
174			return "", errors.Join(userErr, projectErr)
175		}
176		userContent = boundText(userContent, userIndexShareLines, userIndexShareBytes)
177	
178		var out strings.Builder
179		if strings.TrimSpace(userContent) != "" {
180			out.WriteString("<user-memory-index>\n")
181			out.WriteString(strings.TrimSpace(userContent))
182			out.WriteString("\n</user-memory-index>")
183		}
184		usedLines := lineCount(out.String())
185		usedBytes := out.Len()
186		remainingLines := indexMaxLines - usedLines
187		remainingBytes := indexMaxBytes - usedBytes
188		if strings.TrimSpace(projectContent) != "" && remainingLines > 2 && remainingBytes > len("\n\n<project-memory-index>\n\n</project-memory-index>") {
189			if out.Len() > 0 {
190				out.WriteString("\n\n")
191			}
192			open := "<project-memory-index>\n"
193			close := "\n</project-memory-index>"
194			out.WriteString(open)
195			remainingLines = indexMaxLines - lineCount(out.String()) - 1
196			remainingBytes = indexMaxBytes - out.Len() - len(close)
197			out.WriteString(strings.TrimSpace(boundText(projectContent, remainingLines, remainingBytes)))
198			out.WriteString(close)
199		}
200		return boundText(out.String(), indexMaxLines, indexMaxBytes), nil
201	}
