348	func (s *NoteStore) rootFor(scope Scope) (string, error) {
349		switch scope {
350		case ScopeProject:
351			if strings.TrimSpace(s.ProjectRoot) == "" {
352				return "", fmt.Errorf("项目记忆目录未配置")
353			}
354			return s.ProjectRoot, nil
355		case ScopeUser:
356			if strings.TrimSpace(s.UserRoot) == "" {
357				return "", fmt.Errorf("用户记忆目录未配置")
358			}
359			return s.UserRoot, nil
360		default:
361			return "", fmt.Errorf("未知记忆作用域: %s", scope)
362		}
363	}
