390	
391	func marshalNote(note Note) ([]byte, error) {
392		metadata := note
393		metadata.Body = ""
394		frontmatter, err := yaml.Marshal(metadata)
395		if err != nil {
396			return nil, fmt.Errorf("编码记忆 frontmatter 失败: %w", err)
397		}
398		return []byte("---\n" + string(frontmatter) + "---\n\n" + strings.TrimSpace(note.Body) + "\n"), nil
399	}
400	
401	func unmarshalNote(data []byte) (Note, error) {
402		content := strings.ReplaceAll(string(data), "\r\n", "\n")
403		if !strings.HasPrefix(content, "---\n") {
404			return Note{}, fmt.Errorf("记忆文件缺少 frontmatter")
405		}
406		end := strings.Index(content[4:], "\n---\n")
407		if end < 0 {
408			return Note{}, fmt.Errorf("记忆文件 frontmatter 未闭合")
409		}
410		end += 4
411		var note Note
412		if err := yaml.Unmarshal([]byte(content[4:end]), &note); err != nil {
413			return Note{}, fmt.Errorf("解析记忆 frontmatter 失败: %w", err)
414		}
415		note.Body = strings.TrimSpace(content[end+5:])
416		if err := validateNote(note, true); err != nil {
417			return Note{}, err
418		}
419		return note, nil
420	}
421	
422	func validateNote(note Note, requireID bool) error {
423		if err := validateScope(note.Scope); err != nil {
424			return err
425		}
426		if !validCategory(note.Category) {
427			return fmt.Errorf("未知记忆分类: %s", note.Category)
428		}
429		if requireID && !sessionIDPattern.MatchString(note.ID) {
430			return fmt.Errorf("无效记忆 ID: %s", note.ID)
431		}
432		if strings.TrimSpace(note.Title) == "" || strings.TrimSpace(note.Summary) == "" || strings.TrimSpace(note.Body) == "" {
433			return fmt.Errorf("记忆标题、摘要和正文不能为空")
434		}
435		return nil
436	}
437	
438	func validateScope(scope Scope) error {
439		if scope != ScopeProject && scope != ScopeUser {
440			return fmt.Errorf("未知记忆作用域: %s", scope)
441		}
442		return nil
443	}
444	
445	func validCategory(category NoteCategory) bool {
446		switch category {
447		case CategoryPreference, CategoryCorrection, CategoryProjectKnowledge, CategoryReference:
448			return true
449		default:
450			return false
451		}
452	}
453	
454	func equivalentNote(left, right Note) bool {
455		return left.Scope == right.Scope &&
456			left.Category == right.Category &&
457			normalizeMemoryText(left.Title) == normalizeMemoryText(right.Title) &&
458			normalizeMemoryText(left.Summary) == normalizeMemoryText(right.Summary) &&
459			normalizeMemoryText(left.Body) == normalizeMemoryText(right.Body)
460	}
461	
462	func normalizeMemoryText(value string) string {
463		return strings.Join(strings.Fields(strings.ReplaceAll(value, "\r\n", "\n")), " ")
464	}
465	
466	func indexText(value string) string {
467		value = normalizeMemoryText(value)
468		value = strings.ReplaceAll(value, "[", "\\[")
469		return strings.ReplaceAll(value, "]", "\\]")
470	}
471	
472	func atomicWriteFile(path string, data []byte, mode os.FileMode) error {
473		dir := filepath.Dir(path)
474		if err := os.MkdirAll(dir, 0o755); err != nil {
475			return err
476		}
477		temp, err := os.CreateTemp(dir, ".onecode-memory-*")
478		if err != nil {
479			return err
480		}
481		tempPath := temp.Name()
482		defer os.Remove(tempPath)
483		if err := temp.Chmod(mode); err != nil {
484			temp.Close()
485			return err
486		}
487		if _, err := temp.Write(data); err != nil {
488			temp.Close()
489			return err
490		}
491		if err := temp.Sync(); err != nil {
492			temp.Close()
493			return err
494		}
495		if err := temp.Close(); err != nil {
496			return err
497		}
498		return os.Rename(tempPath, path)
499	}
500	
501	func readOptionalFile(path string) (string, error) {
502		if strings.TrimSpace(filepath.Dir(path)) == "." {
503			return "", nil
504		}
505		data, err := os.ReadFile(path)
506		if err != nil {
507			if errors.Is(err, os.ErrNotExist) {
508				return "", nil
509			}
510			return "", fmt.Errorf("读取记忆索引 %s 失败: %w", path, err)
511		}
512		return string(data), nil
513	}
514	
515	func boundText(value string, maxLines, maxBytes int) string {
516		if maxLines <= 0 || maxBytes <= 0 {
517			return ""
518		}
519		value = strings.ReplaceAll(value, "\r\n", "\n")
520		lines := strings.Split(value, "\n")
521		if len(lines) > maxLines {
522			lines = lines[:maxLines]
523		}
524		value = strings.Join(lines, "\n")
525		if len(value) <= maxBytes {
526			return value
527		}
528		value = value[:maxBytes]
529		for !utf8.ValidString(value) {
530			value = value[:len(value)-1]
531		}
532		return value
533	}
534	
535	func lineCount(value string) int {
536		if value == "" {
537			return 0
538		}
539		return strings.Count(value, "\n") + 1
540	}
541	
542	var sensitivePatterns = []*regexp.Regexp{
543		regexp.MustCompile(`(?i)-----BEGIN(?: [A-Z0-9]+)? PRIVATE KEY-----`),
544		regexp.MustCompile(`(?i)\bBearer\s+[A-Za-z0-9._~+/=-]{12,}`),
545		regexp.MustCompile(`\beyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\b`),
546		regexp.MustCompile(`\b(?:sk-ant-|sk-|ghp_|github_pat_|AIza)[A-Za-z0-9_-]{12,}\b`),
547		regexp.MustCompile(`\bAKIA[A-Z0-9]{16}\b`),
548		regexp.MustCompile(`(?i)\b(?:password|passwd|secret|token|api[_-]?key)\s*[:=]\s*["']?[^\s"']{8,}`),
549		regexp.MustCompile(`(?i)\b(?:secret|token|api[_-]?key)\b[^\n]{0,20}\b[A-Za-z0-9+/=_-]{24,}\b`),
550	}
551	
552	func containsSensitiveContent(value string) bool {
553		for _, pattern := range sensitivePatterns {
554			if pattern.MatchString(value) {
555				return true
556			}
557		}
558		return false
559	}

1	package memory
2	
3	import (
4		"fmt"
5		"html"
6		"os"
7		"path/filepath"
8		"strconv"
9		"strings"
10	)
11	
12	const maxInstructionIncludeDepth = 5
13	
14	// LoadWarning describes a non-fatal instruction loading problem.
15	type LoadWarning struct {
16		Path    string
17		Line    int
18		Message string
19	}
20	
21	// InstructionSet is the ordered prompt content loaded for one session.
22	type InstructionSet struct {
23		Content  string
24		Sources  []string
25		Warnings []LoadWarning
26	}
27	
28	// InstructionLoader loads project-local, project-root, and user instructions.
29	type InstructionLoader struct {
30		ProjectRoot string
31		UserRoot    string
32	}
33	
34	// Load reads the configured instruction entrypoints. Missing entrypoints are
35	// normal; invalid includes are returned as warnings while valid content remains.
36	func (l InstructionLoader) Load() InstructionSet {
37		state := instructionLoadState{visited: make(map[string]struct{})}
38		entries := []instructionEntry{
39			{path: filepath.Join(l.ProjectRoot, ".onecode", "ONECODE.md"), allowedRoot: l.ProjectRoot},
40			{path: filepath.Join(l.ProjectRoot, "ONECODE.md"), allowedRoot: l.ProjectRoot},
41		}
42		if strings.TrimSpace(l.UserRoot) != "" {
43			entries = append(entries, instructionEntry{
44				path:        filepath.Join(l.UserRoot, "ONECODE.md"),
45				allowedRoot: l.UserRoot,
46			})
47		}
48	
49		var sections []string
50		for _, entry := range entries {
51			if _, err := os.Stat(entry.path); err != nil {
52				if !os.IsNotExist(err) {
53					state.warn(entry.path, 0, fmt.Sprintf("无法访问指令文件: %v", err))
54				}
55				continue
56			}
57			content, source, ok := state.loadFile(entry.path, entry.allowedRoot, 0)
58			if !ok {
59				continue
60			}
61			sections = append(sections, fmt.Sprintf(
62				"<project-instructions source=\"%s\">\n%s\n</project-instructions>",
63				html.EscapeString(filepath.ToSlash(source)),
64				strings.TrimSpace(content),
65			))
66		}
67	
68		return InstructionSet{
69			Content:  strings.Join(sections, "\n\n"),
70			Sources:  state.sources,
71			Warnings: state.warnings,
72		}
73	}
74	
75	type instructionEntry struct {
76		path        string
77		allowedRoot string
78	}
79	
80	type instructionLoadState struct {
81		visited  map[string]struct{}
82		sources  []string
83		warnings []LoadWarning
84	}
85	
86	func (s *instructionLoadState) loadFile(path, allowedRoot string, depth int) (string, string, bool) {
87		if depth > maxInstructionIncludeDepth {
88			s.warn(path, 0, fmt.Sprintf("@include 超过最大深度 %d", maxInstructionIncludeDepth))
89			return "", "", false
90		}
91		realPath, err := instructionPathWithinRoot(path, allowedRoot)
92		if err != nil {
93			s.warn(path, 0, err.Error())
94			return "", "", false
95		}
96		key := filepath.Clean(realPath)
97		if _, exists := s.visited[key]; exists {
98			s.warn(path, 0, "跳过重复或循环引用")
99			return "", realPath, false
100		}
101		s.visited[key] = struct{}{}
102	
103		data, err := os.ReadFile(realPath)
104		if err != nil {
105			s.warn(realPath, 0, fmt.Sprintf("无法读取指令文件: %v", err))
106			return "", realPath, false
107		}
108		s.sources = append(s.sources, realPath)
109	
110		lines := strings.Split(strings.ReplaceAll(string(data), "\r\n", "\n"), "\n")
111		var out strings.Builder
112		for i, line := range lines {
113			includePath, isInclude, parseErr := parseIncludeDirective(line)
114			switch {
115			case parseErr != nil:
116				s.warn(realPath, i+1, parseErr.Error())
117			case isInclude:
118				target := includePath
119				if !filepath.IsAbs(target) {
120					target = filepath.Join(filepath.Dir(realPath), target)
121				}
122				warningStart := len(s.warnings)
123				included, _, ok := s.loadFile(target, allowedRoot, depth+1)
124				if ok {
125					out.WriteString(included)
126				} else if len(s.warnings) > warningStart {
127					childWarning := s.warnings[warningStart]
128					s.warnings = s.warnings[:warningStart]
129					s.warn(realPath, i+1, fmt.Sprintf("@include %s: %s", includePath, childWarning.Message))
130				}
131			default:
132				out.WriteString(line)
133			}
134			if i < len(lines)-1 {
135				out.WriteByte('\n')
136			}
137		}
138		return out.String(), realPath, true
139	}
140	
141	func parseIncludeDirective(line string) (string, bool, error) {
142		trimmed := strings.TrimSpace(line)
143		if trimmed == "@include" {
144			return "", true, fmt.Errorf("@include 缺少路径")
145		}
146		if !strings.HasPrefix(trimmed, "@include ") && !strings.HasPrefix(trimmed, "@include\t") {
147			return "", false, nil
148		}
149		value := strings.TrimSpace(strings.TrimPrefix(trimmed, "@include"))
150		if value == "" {
151			return "", true, fmt.Errorf("@include 缺少路径")
152		}
153		if strings.HasPrefix(value, "\"") {
154			unquoted, err := strconv.Unquote(value)
155			if err != nil {
156				return "", true, fmt.Errorf("@include 引号路径无效: %v", err)
157			}
158			if strings.TrimSpace(unquoted) == "" {
159				return "", true, fmt.Errorf("@include 缺少路径")
160			}
161			return unquoted, true, nil
162		}
163		return value, true, nil
164	}
165	
166	func instructionPathWithinRoot(path, root string) (string, error) {
167		rootAbs, err := filepath.Abs(root)
168		if err != nil {
169			return "", fmt.Errorf("无法解析允许目录: %w", err)
170		}
171		rootReal, err := filepath.EvalSymlinks(rootAbs)
172		if err != nil {
173			return "", fmt.Errorf("无法解析允许目录符号链接: %w", err)
174		}
175		targetAbs, err := filepath.Abs(path)
176		if err != nil {
177			return "", fmt.Errorf("无法解析引用路径: %w", err)
178		}
179		targetReal, err := filepath.EvalSymlinks(targetAbs)
180		if err != nil {
181			return "", fmt.Errorf("无法解析引用文件: %w", err)
182		}
183		rel, err := filepath.Rel(rootReal, targetReal)
184		if err != nil {
185			return "", fmt.Errorf("无法比较引用路径: %w", err)
186		}
187		if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) || filepath.IsAbs(rel) {
188			return "", fmt.Errorf("引用路径超出允许目录: %s", path)
189		}
190		return targetReal, nil
191	}
192	
193	func (s *instructionLoadState) warn(path string, line int, message string) {
194		s.warnings = append(s.warnings, LoadWarning{Path: path, Line: line, Message: message})
195	}

