81	// Create starts a new append-only session journal.
82	func (s *SessionStore) Create() (*SessionJournal, error) {
83		if err := os.MkdirAll(s.Root, 0o755); err != nil {
84			return nil, fmt.Errorf("创建会话目录失败: %w", err)
85		}
86		for attempt := 0; attempt < 8; attempt++ {
87			id, err := s.newID()
88			if err != nil {
89				return nil, err
90			}
91			journal, err := s.createJournal(id)
92			if err == nil {
93				return journal, nil
94			}
95			if !errors.Is(err, os.ErrExist) {
96				return nil, err
97			}
98		}
99		return nil, fmt.Errorf("创建会话失败: 随机会话 ID 连续冲突")
100	}
