102	// Open reopens an existing session for append without rewriting old records.
103	func (s *SessionStore) Open(id string) (*SessionJournal, error) {
104		path, err := s.sessionPath(id)
105		if err != nil {
106			return nil, err
107		}
108		file, err := os.OpenFile(path, os.O_WRONLY|os.O_APPEND, 0)
109		if err != nil {
110			return nil, fmt.Errorf("打开会话 %s 失败: %w", id, err)
111		}
112		return newSessionJournal(id, path, file, s.clock), nil
113	}
