115	// Load restores one session without modifying its file.
116	func (s *SessionStore) Load(id string) (RestoreResult, error) {
117		path, err := s.sessionPath(id)
118		if err != nil {
119			return RestoreResult{}, err
120		}
121		return s.loadPath(id, path)
122	}
