124	// List returns valid non-empty sessions ordered by last activity descending.
125	func (s *SessionStore) List() ([]SessionInfo, error) {
126		entries, err := os.ReadDir(s.Root)
127		if err != nil {
128			if errors.Is(err, os.ErrNotExist) {
129				return nil, nil
130			}
131			return nil, fmt.Errorf("扫描会话目录失败: %w", err)
132		}
133	
134		infos := make([]SessionInfo, 0, len(entries))
135		for _, entry := range entries {
136			if entry.IsDir() {
137				continue
138			}
139			id, ok := sessionIDFromName(entry.Name())
140			if !ok {
141				continue
142			}
143			result, err := s.loadPath(id, filepath.Join(s.Root, entry.Name()))
144			if err != nil || len(result.Messages) == 0 {
145				continue
146			}
147			infos = append(infos, result.Info)
148		}
149		sort.Slice(infos, func(i, j int) bool {
150			if infos[i].UpdatedAt.Equal(infos[j].UpdatedAt) {
151				return infos[i].ID > infos[j].ID
152			}
153			return infos[i].UpdatedAt.After(infos[j].UpdatedAt)
154		})
155		return infos, nil
156	}
157	
158	// Latest restores the most recent valid session within the retention window.
159	func (s *SessionStore) Latest() (RestoreResult, error) {
160		infos, err := s.List()
161		if err != nil {
162			return RestoreResult{}, err
163		}
164		cutoff := s.clock().Add(-sessionRetention)
165		for _, info := range infos {
166			if info.UpdatedAt.Before(cutoff) {
167				continue
168			}
169			return s.Load(info.ID)
170		}
171		return RestoreResult{}, os.ErrNotExist
172	}
173	
174	// Cleanup removes expired valid sessions while preserving activeIDs.
175	func (s *SessionStore) Cleanup(before time.Time, activeIDs ...string) error {
176		entries, err := os.ReadDir(s.Root)
177		if err != nil {
178			if errors.Is(err, os.ErrNotExist) {
179				return nil
180			}
181			return fmt.Errorf("扫描会话目录失败: %w", err)
182		}
183		active := make(map[string]struct{}, len(activeIDs))
184		for _, id := range activeIDs {
185			active[id] = struct{}{}
186		}
187	
188		var cleanupErrors []error
189		for _, entry := range entries {
190			if entry.IsDir() {
191				continue
192			}
193			id, ok := sessionIDFromName(entry.Name())
194			if !ok {
195				continue
196			}
197			if _, keep := active[id]; keep {
198				continue
199			}
200			path := filepath.Join(s.Root, entry.Name())
201			result, err := s.loadPath(id, path)
202			if err != nil || result.LastActiveAt.IsZero() || !result.LastActiveAt.Before(before) {
203				continue
204			}
205			if err := os.Remove(path); err != nil {
206				cleanupErrors = append(cleanupErrors, fmt.Errorf("删除过期会话 %s 失败: %w", id, err))
207			}
208		}
209		return errors.Join(cleanupErrors...)
210	}
