221	func (s *SessionStore) newID() (string, error) {
222		random := s.random
223		if random == nil {
224			random = rand.Reader
225		}
226		suffix := make([]byte, 2)
227		if _, err := io.ReadFull(random, suffix); err != nil {
228			return "", fmt.Errorf("生成会话 ID 失败: %w", err)
229		}
230		return s.clock().Format("20060102-150405") + "-" + hex.EncodeToString(suffix), nil
231	}
