240	func (s *SessionStore) sessionPath(id string) (string, error) {
241		if !sessionIDPattern.MatchString(id) {
242			return "", fmt.Errorf("无效会话 ID: %s", id)
243		}
244		return filepath.Join(s.Root, id+".jsonl"), nil
245	}
