247	func (s *SessionStore) loadPath(id, path string) (RestoreResult, error) {
248		file, err := os.Open(path)
249		if err != nil {
250			return RestoreResult{}, fmt.Errorf("读取会话 %s 失败: %w", id, err)
251		}
252		defer file.Close()
253	
254		timedMessages := make([]timedMessage, 0)
255		warnings := make([]SessionWarning, 0)
256		reader := bufio.NewReader(file)
257		lineNumber := 0
258		for {
259			line, readErr := reader.ReadBytes('\n')
260			if len(line) > 0 {
261				lineNumber++
262				line = []byte(strings.TrimSuffix(strings.TrimSuffix(string(line), "\n"), "\r"))
263				if len(strings.TrimSpace(string(line))) > 0 {
264					var record SessionRecord
265					if err := json.Unmarshal(line, &record); err != nil {
266						warnings = append(warnings, SessionWarning{Path: path, Line: lineNumber, Message: fmt.Sprintf("JSON 解析失败: %v", err)})
267					} else if err := validateSessionRecord(record); err != nil {
268						warnings = append(warnings, SessionWarning{Path: path, Line: lineNumber, Message: err.Error()})
269					} else if record.Type == RecordMessage {
270						timedMessages = append(timedMessages, timedMessage{message: *record.Message, timestamp: record.Timestamp})
271					} else {
272						timedMessages = timedMessages[:0]
273						for _, message := range record.Messages {
274							timedMessages = append(timedMessages, timedMessage{message: message, timestamp: record.Timestamp})
275						}
276					}
277				}
278			}
279			if readErr != nil {
280				if !errors.Is(readErr, io.EOF) {
281					return RestoreResult{}, fmt.Errorf("读取会话 %s 失败: %w", id, readErr)
282				}
283				break
284			}
285		}
286	
287		prefix, protocolWarning := validMessagePrefix(timedMessages)
288		truncated := prefix < len(timedMessages)
289		if protocolWarning != "" {
290			warnings = append(warnings, SessionWarning{Path: path, Message: protocolWarning})
291		}
292		timedMessages = timedMessages[:prefix]
293		messages := make([]llm.Message, len(timedMessages))
294		for i, message := range timedMessages {
295			messages[i] = message.message
296		}
297		createdAt := sessionCreatedAt(id, s.clock().Location())
298		lastActiveAt := createdAt
299		if len(timedMessages) > 0 {
300			lastActiveAt = timedMessages[len(timedMessages)-1].timestamp
301		}
302		info := SessionInfo{
303			ID:           id,
304			Title:        sessionTitle(messages, id),
305			CreatedAt:    createdAt,
306			UpdatedAt:    lastActiveAt,
307			MessageCount: len(messages),
308			WarningCount: len(warnings),
309		}
310		return RestoreResult{
311			Info:         info,
312			Messages:     messages,
313			LastActiveAt: lastActiveAt,
314			SkippedLines: countLineWarnings(warnings),
315			Truncated:    truncated,
316			Warnings:     warnings,
317		}, nil
318	}
