320	// SessionJournal serializes complete JSONL records for one active session.
321	type SessionJournal struct {
322		mu     sync.Mutex
323		id     string
324		path   string
325		file   *os.File
326		writer *bufio.Writer
327		now    func() time.Time
328		closed bool
329	}
