341	// AppendMessage persists one complete conversation message.
342	func (j *SessionJournal) AppendMessage(message llm.Message) error {
343		return j.appendRecord(SessionRecord{Type: RecordMessage, Timestamp: j.clock(), Message: &message})
344	}
