346	// AppendSnapshot persists the complete effective model-visible history.
347	func (j *SessionJournal) AppendSnapshot(messages []llm.Message) error {
348		return j.appendRecord(SessionRecord{Type: RecordSnapshot, Timestamp: j.clock(), Messages: append([]llm.Message(nil), messages...)})
349	}
