393	type timedMessage struct {
394		message   llm.Message
395		timestamp time.Time
396	}
397	
398	func validateSessionRecord(record SessionRecord) error {
399		if record.Timestamp.IsZero() {
400			return fmt.Errorf("会话记录缺少 timestamp")
401		}
402		switch record.Type {
403		case RecordMessage:
404			if record.Message == nil {
405				return fmt.Errorf("message 记录缺少 message")
406			}
407		case RecordSnapshot:
408			if record.Messages == nil {
409				return fmt.Errorf("snapshot 记录缺少 messages")
410			}
411		default:
412			return fmt.Errorf("未知会话记录类型: %s", record.Type)
413		}
414		return nil
415	}
416	
417	func validMessagePrefix(messages []timedMessage) (int, string) {
418		pending := make([]string, 0)
419		groupStart := -1
420		completed := 0
421		for i, item := range messages {
422			message := item.message
423			switch message.Role {
424			case "user":
425				if len(pending) > completed {
426					return groupStart, "工具调用缺少结果，已截断到最长合法消息前缀"
427				}
428			case "assistant":
429				if len(pending) > completed {
430					return groupStart, "工具调用结果不完整，已截断到最长合法消息前缀"
431				}
432				pending = pending[:0]
433				completed = 0
434				groupStart = -1
435				if len(message.ToolCalls) > 0 {
436					groupStart = i
437					seen := make(map[string]struct{}, len(message.ToolCalls))
438					for _, call := range message.ToolCalls {
439						if strings.TrimSpace(call.ID) == "" {
440							return i, "工具调用缺少 ID，已截断到最长合法消息前缀"
441						}
442						if _, exists := seen[call.ID]; exists {
443							return i, "工具调用 ID 重复，已截断到最长合法消息前缀"
444						}
445						seen[call.ID] = struct{}{}
446						pending = append(pending, call.ID)
447					}
448				}
449			case "tool":
450				if message.ToolResult == nil || groupStart < 0 || completed >= len(pending) {
451					return i, "存在孤立工具结果，已截断到最长合法消息前缀"
452				}
453				if message.ToolResult.ToolUseID != pending[completed] {
454					return groupStart, "工具结果 ID 或顺序不匹配，已截断到最长合法消息前缀"
455				}
456				completed++
457			default:
458				return i, fmt.Sprintf("未知消息角色 %q，已截断到最长合法消息前缀", message.Role)
459			}
460		}
461		if len(pending) > completed {
462			return groupStart, "会话末尾工具调用缺少结果，已截断到最长合法消息前缀"
463		}
464		return len(messages), ""
465	}
466	
467	func sessionTitle(messages []llm.Message, fallback string) string {
468		for _, message := range messages {
469			if message.Role != "user" {
470				continue
471			}
472			content := strings.TrimSpace(strings.ReplaceAll(message.Content, "\r\n", "\n"))
473			firstLine := strings.SplitN(content, "\n", 2)[0]
474			title := strings.Join(strings.Fields(firstLine), " ")
475			if title == "" {
476				continue
477			}
478			runes := []rune(title)
479			if len(runes) > 60 {
480				title = string(runes[:60])
481			}
482			return title
483		}
484		return fallback
485	}
486	
487	func sessionCreatedAt(id string, location *time.Location) time.Time {
488		createdAt, err := time.ParseInLocation("20060102-150405", id[:15], location)
489		if err != nil {
490			return time.Time{}
491		}
492		return createdAt
493	}
494	
495	func sessionIDFromName(name string) (string, bool) {
496		if filepath.Ext(name) != ".jsonl" {
497			return "", false
498		}
499		id := strings.TrimSuffix(name, ".jsonl")
500		return id, sessionIDPattern.MatchString(id)
501	}
502	
503	func countLineWarnings(warnings []SessionWarning) int {
504		count := 0
505		for _, warning := range warnings {
506			if warning.Line > 0 {
507				count++
508			}
509		}
510		return count
511	}

