326	func (s *NoteStore) readNote(scope Scope, id string) (Note, error) {
327		root, err := s.rootFor(scope)
328		if err != nil {
329			return Note{}, err
330		}
331		if !sessionIDPattern.MatchString(id) {
332			return Note{}, fmt.Errorf("无效记忆 ID: %s", id)
333		}
334		data, err := os.ReadFile(filepath.Join(root, "notes", id+".md"))
335		if err != nil {
336			return Note{}, err
337		}
338		note, err := unmarshalNote(data)
339		if err != nil {
340			return Note{}, err
341		}
342		if note.ID != id || note.Scope != scope {
343			return Note{}, fmt.Errorf("记忆 frontmatter 与文件路径不一致")
344		}
345		return note, nil
346	}
