365	func (s *NoteStore) newID() (string, error) {
366		random := s.random
367		if random == nil {
368			random = rand.Reader
369		}
370		suffix := make([]byte, 2)
371		if _, err := io.ReadFull(random, suffix); err != nil {
372			return "", fmt.Errorf("生成记忆 ID 失败: %w", err)
373		}
374		return s.clock().Format("20060102-150405") + "-" + hex.EncodeToString(suffix), nil
375	}
