390	
391	func marshalNote(note Note) ([]byte, error) {
392		metadata := note
393		metadata.Body = ""
394		frontmatter, err := yaml.Marshal(metadata)
395		if err != nil {
396			return nil, fmt.Errorf("编码记忆 frontmatter 失败: %w", err)
397		}
398		return []byte("---\n" + string(frontmatter) + "---\n\n" + strings.TrimSpace(note.Body) + "\n"), nil
399	}
400	
401	func unmarshalNote(data []byte) (Note, error) {
402		content := strings.ReplaceAll(string(data), "\r\n", "\n")
403		if !strings.HasPrefix(content, "---\n") {
404			return Note{}, fmt.Errorf("记忆文件缺少 frontmatter")
405		}
406		end := strings.Index(content[4:], "\n---\n")
407		if end < 0 {
408			return Note{}, fmt.Errorf("记忆文件 frontmatter 未闭合")
409		}
410		end += 4
411		var note Note
412		if err := yaml.Unmarshal([]byte(content[4:end]), &note); err != nil {
413			return Note{}, fmt.Errorf("解析记忆 frontmatter 失败: %w", err)
414		}
415		note.Body = strings.TrimSpace(content[end+5:])
416		if err := validateNote(note, true); err != nil {
417			return Note{}, err
418		}
419		return note, nil
420	}
421	
422	func validateNote(note Note, requireID bool) error {
423		if err := validateScope(note.Scope); err != nil {
424			return err
425		}
426		if !validCategory(note.Category) {
427			return fmt.Errorf("未知记忆分类: %s", note.Category)
428		}
429		if requireID && !sessionIDPattern.MatchString(note.ID) {
430			return fmt.Errorf("无效记忆 ID: %s", note.ID)
431		}
432		if strings.TrimSpace(note.Title) == "" || strings.TrimSpace(note.Summary) == "" || strings.TrimSpace(note.Body) == "" {
433			return fmt.Errorf("记忆标题、摘要和正文不能为空")
434		}
435		return nil
436	}
437	
438	func validateScope(scope Scope) error {
439		if scope != ScopeProject && scope != ScopeUser {
440			return fmt.Errorf("未知记忆作用域: %s", scope)
441		}
442		return nil
443	}
444	
445	func validCategory(category NoteCategory) bool {
446		switch category {
447		case CategoryPreference, CategoryCorrection, CategoryProjectKnowledge, CategoryReference:
448			return true
449		default:
450			return false
451		}
452	}
453	
454	func equivalentNote(left, right Note) bool {
455		return left.Scope == right.Scope &&
456			left.Category == right.Category &&
457			normalizeMemoryText(left.Title) == normalizeMemoryText(right.Title) &&
458			normalizeMemoryText(left.Summary) == normalizeMemoryText(right.Summary) &&
459			normalizeMemoryText(left.Body) == normalizeMemoryText(right.Body)
460	}
461	
462	func normalizeMemoryText(value string) string {
463		return strings.Join(strings.Fields(strings.ReplaceAll(value, "\r\n", "\n")), " ")
464	}
465	
466	func indexText(value string) string {
467		value = normalizeMemoryText(value)
468		value = strings.ReplaceAll(value, "[", "\\[")
469		return strings.ReplaceAll(value, "]", "\\]")
470	}
471	
472	func atomicWriteFile(path string, data []byte, mode os.FileMode) error {
473		dir := filepath.Dir(path)
474		if err := os.MkdirAll(dir, 0o755); err != nil {
475			return err
476		}
477		temp, err := os.CreateTemp(dir, ".onecode-memory-*")
478		if err != nil {
479			return err
480		}
481		tempPath := temp.Name()
482		defer os.Remove(tempPath)
483		if err := temp.Chmod(mode); err != nil {
484			temp.Close()
485			return err
486		}
487		if _, err := temp.Write(data); err != nil {
488			temp.Close()
489			return err
490		}
491		if err := temp.Sync(); err != nil {
492			temp.Close()
493			return err
494		}
495		if err := temp.Close(); err != nil {
496			return err
497		}
498		return os.Rename(tempPath, path)
499	}
500	
501	func readOptionalFile(path string) (string, error) {
502		if strings.TrimSpace(filepath.Dir(path)) == "." {
503			return "", nil
504		}
505		data, err := os.ReadFile(path)
506		if err != nil {
507			if errors.Is(err, os.ErrNotExist) {
508				return "", nil
509			}
510			return "", fmt.Errorf("读取记忆索引 %s 失败: %w", path, err)
511		}
512		return string(data), nil
513	}
514	
515	func boundText(value string, maxLines, maxBytes int) string {
516		if maxLines <= 0 || maxBytes <= 0 {
517			return ""
518		}
519		value = strings.ReplaceAll(value, "\r\n", "\n")
520		lines := strings.Split(value, "\n")
521		if len(lines) > maxLines {
522			lines = lines[:maxLines]
523		}
524		value = strings.Join(lines, "\n")
525		if len(value) <= maxBytes {
526			return value
527		}
528		value = value[:maxBytes]
529		for !utf8.ValidString(value) {
530			value = value[:len(value)-1]
531		}
532		return value
533	}
534	
535	func lineCount(value string) int {
536		if value == "" {
537			return 0
538		}
539		return strings.Count(value, "\n") + 1
540	}
