542	var sensitivePatterns = []*regexp.Regexp{
543		regexp.MustCompile(`(?i)-----BEGIN(?: [A-Z0-9]+)? PRIVATE KEY-----`),
544		regexp.MustCompile(`(?i)\bBearer\s+[A-Za-z0-9._~+/=-]{12,}`),
545		regexp.MustCompile(`\beyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\b`),
546		regexp.MustCompile(`\b(?:sk-ant-|sk-|ghp_|github_pat_|AIza)[A-Za-z0-9_-]{12,}\b`),
547		regexp.MustCompile(`\bAKIA[A-Z0-9]{16}\b`),
548		regexp.MustCompile(`(?i)\b(?:password|passwd|secret|token|api[_-]?key)\s*[:=]\s*["']?[^\s"']{8,}`),
549		regexp.MustCompile(`(?i)\b(?:secret|token|api[_-]?key)\b[^\n]{0,20}\b[A-Za-z0-9+/=_-]{24,}\b`),
550	}
551	
552	func containsSensitiveContent(value string) bool {
553		for _, pattern := range sensitivePatterns {
554			if pattern.MatchString(value) {
555				return true
556			}
557		}
558		return false
559	}

1	package memory
