3	import (
4		"fmt"
5		"html"
6		"os"
7		"path/filepath"
8		"strconv"
9		"strings"
10	)
11	
12	const maxInstructionIncludeDepth = 5
13	
14	// LoadWarning describes a non-fatal instruction loading problem.
15	type LoadWarning struct {
16		Path    string
17		Line    int
18		Message string
19	}
20	
21	// InstructionSet is the ordered prompt content loaded for one session.
22	type InstructionSet struct {
23		Content  string
24		Sources  []string
25		Warnings []LoadWarning
26	}
27	
28	// InstructionLoader loads project-local, project-root, and user instructions.
29	type InstructionLoader struct {
30		ProjectRoot string
31		UserRoot    string
32	}
33	
34	// Load reads the configured instruction entrypoints. Missing entrypoints are
35	// normal; invalid includes are returned as warnings while valid content remains.
36	func (l InstructionLoader) Load() InstructionSet {
37		state := instructionLoadState{visited: make(map[string]struct{})}
38		entries := []instructionEntry{
39			{path: filepath.Join(l.ProjectRoot, ".onecode", "ONECODE.md"), allowedRoot: l.ProjectRoot},
40			{path: filepath.Join(l.ProjectRoot, "ONECODE.md"), allowedRoot: l.ProjectRoot},
41		}
42		if strings.TrimSpace(l.UserRoot) != "" {
43			entries = append(entries, instructionEntry{
44				path:        filepath.Join(l.UserRoot, "ONECODE.md"),
45				allowedRoot: l.UserRoot,
46			})
47		}
48	
49		var sections []string
50		for _, entry := range entries {
51			if _, err := os.Stat(entry.path); err != nil {
52				if !os.IsNotExist(err) {
53					state.warn(entry.path, 0, fmt.Sprintf("无法访问指令文件: %v", err))
54				}
55				continue
56			}
57			content, source, ok := state.loadFile(entry.path, entry.allowedRoot, 0)
58			if !ok {
59				continue
60			}
61			sections = append(sections, fmt.Sprintf(
62				"<project-instructions source=\"%s\">\n%s\n</project-instructions>",
63				html.EscapeString(filepath.ToSlash(source)),
64				strings.TrimSpace(content),
65			))
66		}
67	
68		return InstructionSet{
69			Content:  strings.Join(sections, "\n\n"),
70			Sources:  state.sources,
71			Warnings: state.warnings,
72		}
73	}
74	
75	type instructionEntry struct {
76		path        string
77		allowedRoot string
78	}
79	
80	type instructionLoadState struct {
81		visited  map[string]struct{}
82		sources  []string
83		warnings []LoadWarning
84	}
85	
86	func (s *instructionLoadState) loadFile(path, allowedRoot string, depth int) (string, string, bool) {
87		if depth > maxInstructionIncludeDepth {
88			s.warn(path, 0, fmt.Sprintf("@include 超过最大深度 %d", maxInstructionIncludeDepth))
89			return "", "", false
90		}
91		realPath, err := instructionPathWithinRoot(path, allowedRoot)
92		if err != nil {
93			s.warn(path, 0, err.Error())
94			return "", "", false
95		}
96		key := filepath.Clean(realPath)
97		if _, exists := s.visited[key]; exists {
98			s.warn(path, 0, "跳过重复或循环引用")
99			return "", realPath, false
100		}
101		s.visited[key] = struct{}{}
102	
103		data, err := os.ReadFile(realPath)
104		if err != nil {
105			s.warn(realPath, 0, fmt.Sprintf("无法读取指令文件: %v", err))
106			return "", realPath, false
107		}
108		s.sources = append(s.sources, realPath)
109	
110		lines := strings.Split(strings.ReplaceAll(string(data), "\r\n", "\n"), "\n")
111		var out strings.Builder
112		for i, line := range lines {
113			includePath, isInclude, parseErr := parseIncludeDirective(line)
114			switch {
115			case parseErr != nil:
116				s.warn(realPath, i+1, parseErr.Error())
117			case isInclude:
118				target := includePath
119				if !filepath.IsAbs(target) {
120					target = filepath.Join(filepath.Dir(realPath), target)
121				}
122				warningStart := len(s.warnings)
123				included, _, ok := s.loadFile(target, allowedRoot, depth+1)
124				if ok {
125					out.WriteString(included)
126				} else if len(s.warnings) > warningStart {
127					childWarning := s.warnings[warningStart]
128					s.warnings = s.warnings[:warningStart]
129					s.warn(realPath, i+1, fmt.Sprintf("@include %s: %s", includePath, childWarning.Message))
130				}
131			default:
132				out.WriteString(line)
133			}
134			if i < len(lines)-1 {
135				out.WriteByte('\n')
136			}
137		}
138		return out.String(), realPath, true
139	}
140	
141	func parseIncludeDirective(line string) (string, bool, error) {
142		trimmed := strings.TrimSpace(line)
143		if trimmed == "@include" {
144			return "", true, fmt.Errorf("@include 缺少路径")
145		}
146		if !strings.HasPrefix(trimmed, "@include ") && !strings.HasPrefix(trimmed, "@include\t") {
147			return "", false, nil
148		}
149		value := strings.TrimSpace(strings.TrimPrefix(trimmed, "@include"))
150		if value == "" {
151			return "", true, fmt.Errorf("@include 缺少路径")
152		}
153		if strings.HasPrefix(value, "\"") {
154			unquoted, err := strconv.Unquote(value)
155			if err != nil {
156				return "", true, fmt.Errorf("@include 引号路径无效: %v", err)
157			}
158			if strings.TrimSpace(unquoted) == "" {
159				return "", true, fmt.Errorf("@include 缺少路径")
160			}
161			return unquoted, true, nil
162		}
163		return value, true, nil
164	}
165	
166	func instructionPathWithinRoot(path, root string) (string, error) {
167		rootAbs, err := filepath.Abs(root)
168		if err != nil {
169			return "", fmt.Errorf("无法解析允许目录: %w", err)
170		}
171		rootReal, err := filepath.EvalSymlinks(rootAbs)
172		if err != nil {
173			return "", fmt.Errorf("无法解析允许目录符号链接: %w", err)
174		}
175		targetAbs, err := filepath.Abs(path)
176		if err != nil {
177			return "", fmt.Errorf("无法解析引用路径: %w", err)
178		}
179		targetReal, err := filepath.EvalSymlinks(targetAbs)
180		if err != nil {
181			return "", fmt.Errorf("无法解析引用文件: %w", err)
182		}
183		rel, err := filepath.Rel(rootReal, targetReal)
184		if err != nil {
185			return "", fmt.Errorf("无法比较引用路径: %w", err)
186		}
187		if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) || filepath.IsAbs(rel) {
188			return "", fmt.Errorf("引用路径超出允许目录: %s", path)
189		}
190		return targetReal, nil
191	}
192	
193	func (s *instructionLoadState) warn(path string, line int, message string) {
194		s.warnings = append(s.warnings, LoadWarning{Path: path, Line: line, Message: message})
195	}

