18	
19	const (
20		defaultMemoryQueueSize = 16
21		defaultMemoryTimeout   = 60 * time.Second
22		memoryExtractorSystem  = `You maintain durable coding-agent memory.
23	Extract only information that remains useful beyond the current turn.
24	Return valid JSON only. Never preserve credentials or secrets.`
25	)
26	
27	// TurnCandidate contains one complete naturally-finished Agent turn.
28	type TurnCandidate struct {
29		SessionID string
30		Messages  []llm.Message
31		StoppedAt time.Time
32	}
33	
34	type memoryJob struct {
35		provider  llm.Provider
36		candidate TurnCandidate
37	}
38	
39	// Worker serializes asynchronous memory extraction and note updates.
40	type Worker struct {
41		store   *NoteStore
42		queue   chan memoryJob
43		errors  chan error
44		ctx     context.Context
45		cancel  context.CancelFunc
46		timeout time.Duration
47	
48		mu     sync.Mutex
49		seen   map[string]struct{}
50		closed bool
51		wg     sync.WaitGroup
52	}
53	
54	// NewWorker starts one background memory consumer.
55	func NewWorker(store *NoteStore) *Worker {
56		ctx, cancel := context.WithCancel(context.Background())
57		w := &Worker{
58			store:   store,
59			queue:   make(chan memoryJob, defaultMemoryQueueSize),
60			errors:  make(chan error, defaultMemoryQueueSize),
61			ctx:     ctx,
62			cancel:  cancel,
63			timeout: defaultMemoryTimeout,
64			seen:    make(map[string]struct{}),
65		}
66		w.wg.Add(1)
67		go w.run()
68		return w
69	}
70	
71	// Enqueue submits a useful candidate without blocking the caller.
72	func (w *Worker) Enqueue(provider llm.Provider, candidate TurnCandidate) bool {
73		if w == nil || w.store == nil || !w.store.Enabled || provider == nil || !usefulCandidate(candidate) {
74			return false
75		}
76		hash, err := candidateHash(candidate)
77		if err != nil {
78			w.report(fmt.Errorf("计算记忆候选哈希失败: %w", err))
79			return false
80		}
81	
82		w.mu.Lock()
83		if w.closed {
84			w.mu.Unlock()
85			return false
86		}
87		if _, duplicate := w.seen[hash]; duplicate {
88			w.mu.Unlock()
89			return false
90		}
91		select {
92		case w.queue <- memoryJob{provider: provider, candidate: cloneCandidate(candidate)}:
93			w.seen[hash] = struct{}{}
94			w.mu.Unlock()
95			return true
96		default:
97			w.mu.Unlock()
98			w.report(fmt.Errorf("自动记忆队列已满，已跳过本轮候选"))
99			return false
100		}
101	}
102	
103	// Errors exposes best-effort background failures without blocking the worker.
104	func (w *Worker) Errors() <-chan error {
105		if w == nil {
106			return nil
107		}
108		return w.errors
109	}
110	
111	// Close cancels in-flight extraction and waits for the consumer to exit.
112	func (w *Worker) Close() error {
113		if w == nil {
114			return nil
115		}
116		w.mu.Lock()
117		if w.closed {
118			w.mu.Unlock()
119			return nil
120		}
121		w.closed = true
122		w.cancel()
123		w.mu.Unlock()
124		w.wg.Wait()
125		w.mu.Lock()
126		close(w.errors)
127		w.mu.Unlock()
128		return nil
129	}
130	
131	func (w *Worker) run() {
132		defer w.wg.Done()
133		for {
134			select {
135			case <-w.ctx.Done():
136				return
137			case job := <-w.queue:
138				if err := w.process(job); err != nil && !errors.Is(err, context.Canceled) {
139					w.report(err)
140				}
141			}
142		}
143	}
144	
145	func (w *Worker) process(job memoryJob) error {
146		if w.store == nil || !w.store.Enabled {
147			return nil
148		}
149		indexes, err := w.store.LoadIndexes()
150		if err != nil {
151			return fmt.Errorf("读取自动记忆索引失败: %w", err)
152		}
153		timeout := w.timeout
154		if timeout <= 0 {
155			timeout = defaultMemoryTimeout
156		}
157		ctx, cancel := context.WithTimeout(w.ctx, timeout)
158		defer cancel()
159	
160		text, err := extractMemory(ctx, job.provider, buildMemoryPrompt(job.candidate, indexes))
161		if err != nil {
162			return err
163		}
164		mutations, err := parseMemoryMutations(text)
165		if err != nil {
166			return err
167		}
168		mutations, err = validateMemoryMutations(mutations, job.candidate)
169		if err != nil {
170			return err
171		}
172		if len(mutations) == 0 {
173			return nil
174		}
175		if err := w.store.Apply(mutations); err != nil {
176			return fmt.Errorf("应用自动记忆失败: %w", err)
177		}
178		return nil
179	}
180	
181	func (w *Worker) report(err error) {
182		if w == nil || err == nil {
183			return
184		}
185		w.mu.Lock()
186		defer w.mu.Unlock()
187		if w.closed {
188			return
189		}
190		select {
191		case w.errors <- err:
192		default:
193		}
194	}
195	
196	func extractMemory(ctx context.Context, provider llm.Provider, extractionPrompt string) (string, error) {
197		events, errs := provider.Stream(ctx, []llm.Message{{Role: "user", Content: extractionPrompt}}, nil, llm.StreamOptions{})
198		var text strings.Builder
199		for events != nil || errs != nil {
200			select {
201			case <-ctx.Done():
202				return "", ctx.Err()
203			case event, ok := <-events:
204				if !ok {
205					events = nil
206					continue
207				}
208				if event.ToolCall != nil {
209					return "", fmt.Errorf("自动记忆提取不允许工具调用: %s", event.ToolCall.Name)
210				}
211				text.WriteString(event.Text)
212				if event.Done {
213					if strings.TrimSpace(text.String()) == "" {
214						return "", fmt.Errorf("自动记忆提取返回空响应")
215					}
216					return text.String(), nil
217				}
218			case err, ok := <-errs:
219				if !ok {
220					errs = nil
221					continue
222				}
223				if err != nil {
224					return "", fmt.Errorf("自动记忆提取流失败: %w", err)
225				}
226			}
227		}
228		return "", fmt.Errorf("自动记忆提取流未正常结束")
229	}
230	
231	func buildMemoryPrompt(candidate TurnCandidate, indexes string) string {
232		var builder strings.Builder
233		builder.WriteString(memoryExtractorSystem)
234		builder.WriteString(`
235	
236	Analyze the completed coding-agent turn and decide whether it contains durable memory.
237	
238	Rules:
239	- Prefer project scope for repository facts, commands, conventions, corrections, and references.
240	- Use user scope only for an explicit preference that should apply across projects.
241	- A one-time request is not a user-level preference.
242	- Use update when an existing indexed note should be corrected or extended.
243	- Never include passwords, API keys, access tokens, private keys, or other credentials.
244	- Return exactly one JSON object: {"mutations":[...]}
245	- Each mutation uses operation skip, create, or update.
246	- create/update note fields are scope, category, title, summary, and body.
247	- update also requires target_id from the supplied index.
248	
249	Existing memory indexes:
250	`)
251		if strings.TrimSpace(indexes) == "" {
252			builder.WriteString("(none)")
253		} else {
254			builder.WriteString(indexes)
255		}
256		builder.WriteString("\n\nCompleted turn:\n")
257		builder.WriteString(candidateTranscript(candidate.Messages))
258		return builder.String()
259	}
260	
261	func candidateTranscript(messages []llm.Message) string {
262		var builder strings.Builder
263		for _, message := range messages {
264			builder.WriteString("[" + message.Role + "]\n")
265			if message.Content != "" {
266				builder.WriteString(boundText(message.Content, 80, 8*1024))
267				builder.WriteByte('\n')
268			}
269			for _, call := range message.ToolCalls {
270				builder.WriteString("tool_call: " + call.Name + "\n")
271			}
272			if message.ToolResult != nil {
273				builder.WriteString("tool_result: ")
274				builder.WriteString(boundText(message.ToolResult.Content, 30, 3*1024))
275				builder.WriteByte('\n')
276			}
277		}
278		return boundText(builder.String(), 400, 48*1024)
279	}
280	
281	type mutationEnvelope struct {
282		Mutations []NoteMutation `json:"mutations"`
283	}
284	
285	func parseMemoryMutations(value string) ([]NoteMutation, error) {
286		value = stripJSONFence(value)
287		var envelope mutationEnvelope
288		if err := strictJSON([]byte(value), &envelope); err == nil && envelope.Mutations != nil {
289			return envelope.Mutations, nil
290		}
291		var mutations []NoteMutation
292		if err := strictJSON([]byte(value), &mutations); err != nil {
293			return nil, fmt.Errorf("解析自动记忆 JSON 失败: %w", err)
294		}
295		return mutations, nil
296	}
297	
298	func strictJSON(data []byte, target any) error {
299		decoder := json.NewDecoder(strings.NewReader(string(data)))
300		decoder.DisallowUnknownFields()
301		if err := decoder.Decode(target); err != nil {
302			return err
303		}
304		var extra any
305		if err := decoder.Decode(&extra); !errors.Is(err, io.EOF) {
306			if err == nil {
307				return fmt.Errorf("JSON 包含多余内容")
308			}
309			return err
310		}
311		return nil
312	}
313	
314	func stripJSONFence(value string) string {
315		value = strings.TrimSpace(value)
316		if !strings.HasPrefix(value, "```") {
317			return value
318		}
319		firstNewline := strings.IndexByte(value, '\n')
320		lastFence := strings.LastIndex(value, "```")
321		if firstNewline < 0 || lastFence <= firstNewline {
322			return value
323		}
324		return strings.TrimSpace(value[firstNewline+1 : lastFence])
325	}
326	
327	func validateMemoryMutations(mutations []NoteMutation, candidate TurnCandidate) ([]NoteMutation, error) {
328		validated := make([]NoteMutation, 0, len(mutations))
329		for _, mutation := range mutations {
330			switch mutation.Operation {
331			case MutationSkip:
332				continue
333			case MutationCreate, MutationUpdate:
334			default:
335				return nil, fmt.Errorf("自动记忆返回未知操作: %s", mutation.Operation)
336			}
337			if mutation.Note.Scope == "" {
338				mutation.Note.Scope = ScopeProject
339			}
340			if err := validateScope(mutation.Note.Scope); err != nil {
341				return nil, err
342			}
343			if !validCategory(mutation.Note.Category) {
344				return nil, fmt.Errorf("自动记忆返回未知分类: %s", mutation.Note.Category)
345			}
346			if mutation.Operation == MutationUpdate && !sessionIDPattern.MatchString(mutation.TargetID) {
347				return nil, fmt.Errorf("自动记忆 update 缺少合法 target_id")
348			}
349			if mutation.Operation == MutationCreate && mutation.Note.Scope == ScopeUser {
350				if mutation.Note.Category != CategoryPreference || !explicitGlobalPreference(candidate.Messages) {
351					mutation.Note.Scope = ScopeProject
352				}
353			}
354			if strings.TrimSpace(mutation.Note.Title) == "" || strings.TrimSpace(mutation.Note.Summary) == "" || strings.TrimSpace(mutation.Note.Body) == "" {
355				return nil, fmt.Errorf("自动记忆标题、摘要和正文不能为空")
356			}
357			if containsSensitiveContent(strings.Join([]string{mutation.Note.Title, mutation.Note.Summary, mutation.Note.Body}, "\n")) {
358				continue
359			}
360			mutation.Note.ID = ""
361			mutation.Note.CreatedAt = time.Time{}
362			mutation.Note.UpdatedAt = time.Time{}
363			mutation.Note.SourceSessionID = candidate.SessionID
364			validated = append(validated, mutation)
365		}
366		return validated, nil
367	}
368	
369	func explicitGlobalPreference(messages []llm.Message) bool {
370		var userText strings.Builder
371		for _, message := range messages {
372			if message.Role == "user" {
373				userText.WriteString(" ")
374				userText.WriteString(strings.ToLower(message.Content))
375			}
376		}
377		value := userText.String()
378		for _, marker := range []string{
379			"所有项目", "每个项目", "跨项目", "全局偏好", "以后都", "总是",
380			"all projects", "every project", "across projects", "global preference", "always",
381		} {
382			if strings.Contains(value, marker) {
383				return true
384			}
385		}
386		return false
387	}
388	
389	func usefulCandidate(candidate TurnCandidate) bool {
390		var userText, assistantText strings.Builder
391		for _, message := range candidate.Messages {
392			switch message.Role {
393			case "user":
394				userText.WriteString(" ")
395				userText.WriteString(message.Content)
396			case "assistant":
397				assistantText.WriteString(" ")
398				assistantText.WriteString(message.Content)
399			}
400		}
401		user := strings.TrimSpace(userText.String())
402		assistant := strings.TrimSpace(assistantText.String())
403		if user == "" || assistant == "" {
404			return false
405		}
406		normalizedUser := strings.ToLower(strings.Join(strings.Fields(user), " "))
407		for _, short := range []string{"hi", "hello", "ok", "okay", "thanks", "thank you", "你好", "好的", "谢谢", "确认", "1"} {
408			if normalizedUser == short {
409				return false
410			}
411		}
412		return utf8.RuneCountInString(user)+utf8.RuneCountInString(assistant) >= 40
413	}
414	
415	func candidateHash(candidate TurnCandidate) (string, error) {
416		data, err := json.Marshal(candidate.Messages)
417		if err != nil {
418			return "", err
419		}
420		sum := sha256.Sum256(data)
421		return hex.EncodeToString(sum[:]), nil
422	}
423	
424	func cloneCandidate(candidate TurnCandidate) TurnCandidate {
425		candidate.Messages = append([]llm.Message(nil), candidate.Messages...)
426		return candidate
427	}

