14		"time"
15		"unicode/utf8"
16	
17		"gopkg.in/yaml.v3"
18	)
19	
20	const (
21		indexMaxLines       = 200
22		indexMaxBytes       = 25 * 1024
23		userIndexShareLines = indexMaxLines / 4
24		userIndexShareBytes = indexMaxBytes / 4
25	)
26	
27	// Scope identifies whether a note belongs to the current project or the user.
28	type Scope string
29	
30	const (
31		ScopeUser    Scope = "user"
32		ScopeProject Scope = "project"
33	)
34	
35	// NoteCategory classifies durable memory content.
36	type NoteCategory string
37	
38	const (
39		CategoryPreference       NoteCategory = "preference"
40		CategoryCorrection       NoteCategory = "correction"
41		CategoryProjectKnowledge NoteCategory = "project_knowledge"
42		CategoryReference        NoteCategory = "reference"
43	)
44	
45	// Note is one user-readable Markdown memory item.
46	type Note struct {
47		ID              string       `yaml:"id" json:"id"`
48		Scope           Scope        `yaml:"scope" json:"scope"`
49		Category        NoteCategory `yaml:"category" json:"category"`
50		Title           string       `yaml:"title" json:"title"`
51		Summary         string       `yaml:"summary" json:"summary"`
52		SourceSessionID string       `yaml:"source_session_id,omitempty" json:"source_session_id,omitempty"`
53		CreatedAt       time.Time    `yaml:"created_at" json:"created_at,omitempty"`
54		UpdatedAt       time.Time    `yaml:"updated_at" json:"updated_at,omitempty"`
55		Body            string       `yaml:"-" json:"body"`
56	}
57	
58	// MutationOperation is the only set of changes accepted from the memory LLM.
59	type MutationOperation string
60	
61	const (
62		MutationSkip   MutationOperation = "skip"
63		MutationCreate MutationOperation = "create"
64		MutationUpdate MutationOperation = "update"
65	)
66	
67	// NoteMutation requests one validated local note change.
68	type NoteMutation struct {
69		Operation MutationOperation `json:"operation"`
70		TargetID  string            `json:"target_id,omitempty"`
71		Note      Note              `json:"note,omitempty"`
72	}
73	
74	// NoteStore owns user and project Markdown memory roots.
75	type NoteStore struct {
76		UserRoot    string
77		ProjectRoot string
78		Enabled     bool
79		now         func() time.Time
80		random      io.Reader
81		write       func(string, []byte, os.FileMode) error
82	}
83	
84	// NewNoteStore creates user- and project-scoped memory stores.
85	func NewNoteStore(projectRoot, userHome string, enabled bool) *NoteStore {
86		userRoot := ""
87		if strings.TrimSpace(userHome) != "" {
88			userRoot = filepath.Join(userHome, ".onecode", "memory")
89		}
90		return &NoteStore{
91			ProjectRoot: filepath.Join(projectRoot, ".onecode", "memory"),
92			UserRoot:    userRoot,
93			Enabled:     enabled,
94		}
95	}
96	
97	// Apply validates local storage invariants, writes notes, then rebuilds indexes.
98	func (s *NoteStore) Apply(mutations []NoteMutation) error {
99		if !s.Enabled {
100			return nil
101		}
102		for _, mutation := range mutations {
103			switch mutation.Operation {
104			case MutationSkip:
105				continue
106			case MutationCreate:
107				changed, scope, err := s.create(mutation.Note)
108				if err != nil {
109					return err
110				}
111				if changed {
112					if err := s.RebuildIndex(scope); err != nil {
113						return err
114					}
115				}
116			case MutationUpdate:
117				changed, scope, err := s.update(mutation.TargetID, mutation.Note)
118				if err != nil {
119					return err
120				}
121				if changed {
122					if err := s.RebuildIndex(scope); err != nil {
123						return err
124					}
125				}
126			default:
127				return fmt.Errorf("未知记忆操作: %s", mutation.Operation)
128			}
129		}
130		return nil
131	}
132	
133	// RebuildIndex regenerates one scope's bounded INDEX.md from actual notes.
134	func (s *NoteStore) RebuildIndex(scope Scope) error {
135		root, err := s.rootFor(scope)
136		if err != nil {
137			return err
138		}
139		notes, err := s.readAllNotes(scope)
140		if err != nil {
141			return err
142		}
143		sort.Slice(notes, func(i, j int) bool {
144			if notes[i].UpdatedAt.Equal(notes[j].UpdatedAt) {
145				return notes[i].ID < notes[j].ID
146			}
147			return notes[i].UpdatedAt.After(notes[j].UpdatedAt)
148		})
149	
150		lines := []string{"# OneCode Memory Index", ""}
151		for _, note := range notes {
152			line := fmt.Sprintf("- [%s](notes/%s.md) [%s] - %s",
153				indexText(note.Title), note.ID, note.Category, indexText(note.Summary))
154			lines = append(lines, line)
155		}
156		content := boundText(strings.Join(lines, "\n")+"\n", indexMaxLines, indexMaxBytes)
157		if err := os.MkdirAll(root, 0o755); err != nil {
158			return fmt.Errorf("创建记忆目录失败: %w", err)
159		}
160		if err := s.writeFile(filepath.Join(root, "INDEX.md"), []byte(content), 0o600); err != nil {
161			return fmt.Errorf("更新 %s 记忆索引失败: %w", scope, err)
162		}
163		return nil
164	}
165	
166	// LoadIndexes returns bounded user and project indexes for one model request.
167	func (s *NoteStore) LoadIndexes() (string, error) {
168		if !s.Enabled {
169			return "", nil
170		}
171		userContent, userErr := readOptionalFile(filepath.Join(s.UserRoot, "INDEX.md"))
172		projectContent, projectErr := readOptionalFile(filepath.Join(s.ProjectRoot, "INDEX.md"))
173		if userErr != nil || projectErr != nil {
174			return "", errors.Join(userErr, projectErr)
175		}
176		userContent = boundText(userContent, userIndexShareLines, userIndexShareBytes)
177	
178		var out strings.Builder
179		if strings.TrimSpace(userContent) != "" {
180			out.WriteString("<user-memory-index>\n")
181			out.WriteString(strings.TrimSpace(userContent))
182			out.WriteString("\n</user-memory-index>")
183		}
184		usedLines := lineCount(out.String())
185		usedBytes := out.Len()
186		remainingLines := indexMaxLines - usedLines
187		remainingBytes := indexMaxBytes - usedBytes
188		if strings.TrimSpace(projectContent) != "" && remainingLines > 2 && remainingBytes > len("\n\n<project-memory-index>\n\n</project-memory-index>") {
189			if out.Len() > 0 {
190				out.WriteString("\n\n")
191			}
192			open := "<project-memory-index>\n"
193			close := "\n</project-memory-index>"
194			out.WriteString(open)
195			remainingLines = indexMaxLines - lineCount(out.String()) - 1
196			remainingBytes = indexMaxBytes - out.Len() - len(close)
197			out.WriteString(strings.TrimSpace(boundText(projectContent, remainingLines, remainingBytes)))
198			out.WriteString(close)
199		}
200		return boundText(out.String(), indexMaxLines, indexMaxBytes), nil
201	}
202	
203	func (s *NoteStore) create(note Note) (bool, Scope, error) {
204		if err := validateNote(note, false); err != nil {
205			return false, note.Scope, err
206		}
207		notes, err := s.readAllNotes(note.Scope)
208		if err != nil {
209			return false, note.Scope, err
210		}
211		for _, existing := range notes {
212			if equivalentNote(existing, note) {
213				return false, note.Scope, nil
214			}
215		}
216		var id string
217		for attempt := 0; attempt < 8; attempt++ {
218			candidate, err := s.newID()
219			if err != nil {
220				return false, note.Scope, err
221			}
222			root, err := s.rootFor(note.Scope)
223			if err != nil {
224				return false, note.Scope, err
225			}
226			if _, err := os.Stat(filepath.Join(root, "notes", candidate+".md")); errors.Is(err, os.ErrNotExist) {
227				id = candidate
228				break
229			} else if err != nil {
230				return false, note.Scope, err
231			}
232		}
233		if id == "" {
234			return false, note.Scope, fmt.Errorf("创建记忆失败: 随机记忆 ID 连续冲突")
235		}
236		now := s.clock()
237		note.ID = id
238		note.CreatedAt = now
239		note.UpdatedAt = now
240		if err := s.persistNote(note); err != nil {
241			return false, note.Scope, err
242		}
243		return true, note.Scope, nil
244	}
245	
246	func (s *NoteStore) update(targetID string, replacement Note) (bool, Scope, error) {
247		if !sessionIDPattern.MatchString(targetID) {
248			return false, replacement.Scope, fmt.Errorf("无效记忆 ID: %s", targetID)
249		}
250		if err := validateScope(replacement.Scope); err != nil {
251			return false, replacement.Scope, err
252		}
253		existing, err := s.readNote(replacement.Scope, targetID)
254		if err != nil {
255			return false, replacement.Scope, fmt.Errorf("更新目标 %s 不存在或不可读: %w", targetID, err)
256		}
257		replacement.ID = existing.ID
258		replacement.CreatedAt = existing.CreatedAt
259		replacement.UpdatedAt = s.clock()
260		if replacement.SourceSessionID == "" {
261			replacement.SourceSessionID = existing.SourceSessionID
262		}
263		if err := validateNote(replacement, true); err != nil {
264			return false, replacement.Scope, err
265		}
266		if equivalentNote(existing, replacement) {
267			return false, replacement.Scope, nil
268		}
269		if err := s.persistNote(replacement); err != nil {
270			return false, replacement.Scope, err
271		}
272		return true, replacement.Scope, nil
273	}
274	
275	func (s *NoteStore) persistNote(note Note) error {
276		root, err := s.rootFor(note.Scope)
277		if err != nil {
278			return err
279		}
280		dir := filepath.Join(root, "notes")
281		if err := os.MkdirAll(dir, 0o755); err != nil {
282			return fmt.Errorf("创建记忆笔记目录失败: %w", err)
283		}
284		data, err := marshalNote(note)
285		if err != nil {
286			return err
287		}
288		path := filepath.Join(dir, note.ID+".md")
289		if err := s.writeFile(path, data, 0o600); err != nil {
290			return fmt.Errorf("写入记忆笔记 %s 失败: %w", note.ID, err)
291		}
292		return nil
293	}
294	
295	func (s *NoteStore) readAllNotes(scope Scope) ([]Note, error) {
296		root, err := s.rootFor(scope)
297		if err != nil {
298			return nil, err
299		}
300		dir := filepath.Join(root, "notes")
301		entries, err := os.ReadDir(dir)
302		if err != nil {
303			if errors.Is(err, os.ErrNotExist) {
304				return nil, nil
305			}
306			return nil, fmt.Errorf("读取记忆笔记目录失败: %w", err)
307		}
308		notes := make([]Note, 0, len(entries))
309		for _, entry := range entries {
310			if entry.IsDir() || filepath.Ext(entry.Name()) != ".md" {
311				continue
312			}
313			id := strings.TrimSuffix(entry.Name(), ".md")
314			if !sessionIDPattern.MatchString(id) {
315				continue
316			}
317			note, err := s.readNote(scope, id)
318			if err != nil {
319				continue
320			}
321			notes = append(notes, note)
322		}
323		return notes, nil
324	}
325	
326	func (s *NoteStore) readNote(scope Scope, id string) (Note, error) {
327		root, err := s.rootFor(scope)
328		if err != nil {
329			return Note{}, err
330		}
331		if !sessionIDPattern.MatchString(id) {
332			return Note{}, fmt.Errorf("无效记忆 ID: %s", id)
333		}
334		data, err := os.ReadFile(filepath.Join(root, "notes", id+".md"))
335		if err != nil {
336			return Note{}, err
337		}
338		note, err := unmarshalNote(data)
339		if err != nil {
340			return Note{}, err
341		}
342		if note.ID != id || note.Scope != scope {
343			return Note{}, fmt.Errorf("记忆 frontmatter 与文件路径不一致")
344		}
345		return note, nil
346	}
347	
348	func (s *NoteStore) rootFor(scope Scope) (string, error) {
349		switch scope {
350		case ScopeProject:
351			if strings.TrimSpace(s.ProjectRoot) == "" {
352				return "", fmt.Errorf("项目记忆目录未配置")
353			}
354			return s.ProjectRoot, nil
355		case ScopeUser:
356			if strings.TrimSpace(s.UserRoot) == "" {
357				return "", fmt.Errorf("用户记忆目录未配置")
358			}
359			return s.UserRoot, nil
360		default:
361			return "", fmt.Errorf("未知记忆作用域: %s", scope)
362		}
363	}
364	
365	func (s *NoteStore) newID() (string, error) {
366		random := s.random
367		if random == nil {
368			random = rand.Reader
369		}
370		suffix := make([]byte, 2)
371		if _, err := io.ReadFull(random, suffix); err != nil {
372			return "", fmt.Errorf("生成记忆 ID 失败: %w", err)
373		}
374		return s.clock().Format("20060102-150405") + "-" + hex.EncodeToString(suffix), nil
375	}
376	
377	func (s *NoteStore) clock() time.Time {
378		if s.now != nil {
379			return s.now()
380		}
381		return time.Now()
382	}
383	
384	func (s *NoteStore) writeFile(path string, data []byte, mode os.FileMode) error {
385		if s.write != nil {
386			return s.write(path, data, mode)
387		}
388		return atomicWriteFile(path, data, mode)
389	}
390	
391	func marshalNote(note Note) ([]byte, error) {
392		metadata := note
393		metadata.Body = ""
394		frontmatter, err := yaml.Marshal(metadata)
395		if err != nil {
396			return nil, fmt.Errorf("编码记忆 frontmatter 失败: %w", err)
397		}
398		return []byte("---\n" + string(frontmatter) + "---\n\n" + strings.TrimSpace(note.Body) + "\n"), nil
399	}
400	
401	func unmarshalNote(data []byte) (Note, error) {
402		content := strings.ReplaceAll(string(data), "\r\n", "\n")
403		if !strings.HasPrefix(content, "---\n") {
404			return Note{}, fmt.Errorf("记忆文件缺少 frontmatter")
405		}
406		end := strings.Index(content[4:], "\n---\n")
407		if end < 0 {
408			return Note{}, fmt.Errorf("记忆文件 frontmatter 未闭合")
409		}
410		end += 4
411		var note Note
412		if err := yaml.Unmarshal([]byte(content[4:end]), &note); err != nil {
413			return Note{}, fmt.Errorf("解析记忆 frontmatter 失败: %w", err)
414		}
415		note.Body = strings.TrimSpace(content[end+5:])
416		if err := validateNote(note, true); err != nil {
417			return Note{}, err
418		}
419		return note, nil
420	}
421	
422	func validateNote(note Note, requireID bool) error {
423		if err := validateScope(note.Scope); err != nil {
424			return err
425		}
426		if !validCategory(note.Category) {
427			return fmt.Errorf("未知记忆分类: %s", note.Category)
428		}
429		if requireID && !sessionIDPattern.MatchString(note.ID) {
430			return fmt.Errorf("无效记忆 ID: %s", note.ID)
431		}
432		if strings.TrimSpace(note.Title) == "" || strings.TrimSpace(note.Summary) == "" || strings.TrimSpace(note.Body) == "" {
433			return fmt.Errorf("记忆标题、摘要和正文不能为空")
434		}
435		return nil
436	}
437	
438	func validateScope(scope Scope) error {
439		if scope != ScopeProject && scope != ScopeUser {
440			return fmt.Errorf("未知记忆作用域: %s", scope)
441		}
442		return nil
443	}
444	
445	func validCategory(category NoteCategory) bool {
446		switch category {
447		case CategoryPreference, CategoryCorrection, CategoryProjectKnowledge, CategoryReference:
448			return true
449		default:
450			return false
451		}
452	}
453	
454	func equivalentNote(left, right Note) bool {
455		return left.Scope == right.Scope &&
456			left.Category == right.Category &&
457			normalizeMemoryText(left.Title) == normalizeMemoryText(right.Title) &&
458			normalizeMemoryText(left.Summary) == normalizeMemoryText(right.Summary) &&
459			normalizeMemoryText(left.Body) == normalizeMemoryText(right.Body)
460	}
461	
462	func normalizeMemoryText(value string) string {
463		return strings.Join(strings.Fields(strings.ReplaceAll(value, "\r\n", "\n")), " ")
464	}
465	
466	func indexText(value string) string {
467		value = normalizeMemoryText(value)
468		value = strings.ReplaceAll(value, "[", "\\[")
469		return strings.ReplaceAll(value, "]", "\\]")
470	}
471	
472	func atomicWriteFile(path string, data []byte, mode os.FileMode) error {
473		dir := filepath.Dir(path)
474		if err := os.MkdirAll(dir, 0o755); err != nil {
475			return err
476		}
477		temp, err := os.CreateTemp(dir, ".onecode-memory-*")
478		if err != nil {
479			return err
480		}
481		tempPath := temp.Name()
482		defer os.Remove(tempPath)
483		if err := temp.Chmod(mode); err != nil {
484			temp.Close()
485			return err
486		}
487		if _, err := temp.Write(data); err != nil {
488			temp.Close()
489			return err
490		}
491		if err := temp.Sync(); err != nil {
492			temp.Close()
493			return err
494		}
495		if err := temp.Close(); err != nil {
496			return err
497		}
498		return os.Rename(tempPath, path)
499	}
500	
501	func readOptionalFile(path string) (string, error) {
502		if strings.TrimSpace(filepath.Dir(path)) == "." {
503			return "", nil
504		}
505		data, err := os.ReadFile(path)
506		if err != nil {
507			if errors.Is(err, os.ErrNotExist) {
508				return "", nil
509			}
510			return "", fmt.Errorf("读取记忆索引 %s 失败: %w", path, err)
511		}
512		return string(data), nil
513	}
514	
515	func boundText(value string, maxLines, maxBytes int) string {
516		if maxLines <= 0 || maxBytes <= 0 {
517			return ""
518		}
519		value = strings.ReplaceAll(value, "\r\n", "\n")
520		lines := strings.Split(value, "\n")
521		if len(lines) > maxLines {
522			lines = lines[:maxLines]
523		}
524		value = strings.Join(lines, "\n")
525		if len(value) <= maxBytes {
526			return value
527		}
528		value = value[:maxBytes]
529		for !utf8.ValidString(value) {
530			value = value[:len(value)-1]
531		}
532		return value
533	}
534	
535	func lineCount(value string) int {
536		if value == "" {
537			return 0
538		}
539		return strings.Count(value, "\n") + 1
540	}
