84	// NewNoteStore creates user- and project-scoped memory stores.
85	func NewNoteStore(projectRoot, userHome string, enabled bool) *NoteStore {
86		userRoot := ""
87		if strings.TrimSpace(userHome) != "" {
88			userRoot = filepath.Join(userHome, ".onecode", "memory")
89		}
90		return &NoteStore{
91			ProjectRoot: filepath.Join(projectRoot, ".onecode", "memory"),
92			UserRoot:    userRoot,
93			Enabled:     enabled,
