203	func (s *NoteStore) create(note Note) (bool, Scope, error) {
204		if err := validateNote(note, false); err != nil {
205			return false, note.Scope, err
206		}
207		notes, err := s.readAllNotes(note.Scope)
208		if err != nil {
209			return false, note.Scope, err
210		}
211		for _, existing := range notes {
212			if equivalentNote(existing, note) {
213				return false, note.Scope, nil
214			}
215		}
216		var id string
217		for attempt := 0; attempt < 8; attempt++ {
218			candidate, err := s.newID()
219			if err != nil {
220				return false, note.Scope, err
221			}
222			root, err := s.rootFor(note.Scope)
223			if err != nil {
224				return false, note.Scope, err
225			}
226			if _, err := os.Stat(filepath.Join(root, "notes", candidate+".md")); errors.Is(err, os.ErrNotExist) {
227				id = candidate
228				break
229			} else if err != nil {
230				return false, note.Scope, err
231			}
232		}
233		if id == "" {
234			return false, note.Scope, fmt.Errorf("创建记忆失败: 随机记忆 ID 连续冲突")
235		}
236		now := s.clock()
237		note.ID = id
238		note.CreatedAt = now
239		note.UpdatedAt = now
240		if err := s.persistNote(note); err != nil {
241			return false, note.Scope, err
242		}
243		return true, note.Scope, nil
244	}
245	
246	func (s *NoteStore) update(targetID string, replacement Note) (bool, Scope, error) {
247		if !sessionIDPattern.MatchString(targetID) {
248			return false, replacement.Scope, fmt.Errorf("无效记忆 ID: %s", targetID)
249		}
250		if err := validateScope(replacement.Scope); err != nil {
251			return false, replacement.Scope, err
252		}
253		existing, err := s.readNote(replacement.Scope, targetID)
254		if err != nil {
255			return false, replacement.Scope, fmt.Errorf("更新目标 %s 不存在或不可读: %w", targetID, err)
256		}
257		replacement.ID = existing.ID
258		replacement.CreatedAt = existing.CreatedAt
259		replacement.UpdatedAt = s.clock()
260		if replacement.SourceSessionID == "" {
261			replacement.SourceSessionID = existing.SourceSessionID
262		}
263		if err := validateNote(replacement, true); err != nil {
264			return false, replacement.Scope, err
265		}
266		if equivalentNote(existing, replacement) {
267			return false, replacement.Scope, nil
268		}
269		if err := s.persistNote(replacement); err != nil {
270			return false, replacement.Scope, err
271		}
272		return true, replacement.Scope, nil
273	}
274	
275	func (s *NoteStore) persistNote(note Note) error {
276		root, err := s.rootFor(note.Scope)
277		if err != nil {
278			return err
279		}
280		dir := filepath.Join(root, "notes")
281		if err := os.MkdirAll(dir, 0o755); err != nil {
282			return fmt.Errorf("创建记忆笔记目录失败: %w", err)
283		}
284		data, err := marshalNote(note)
285		if err != nil {
286			return err
287		}
288		path := filepath.Join(dir, note.ID+".md")
289		if err := s.writeFile(path, data, 0o600); err != nil {
290			return fmt.Errorf("写入记忆笔记 %s 失败: %w", note.ID, err)
291		}
292		return nil
293	}
294	
295	func (s *NoteStore) readAllNotes(scope Scope) ([]Note, error) {
296		root, err := s.rootFor(scope)
297		if err != nil {
298			return nil, err
299		}
300		dir := filepath.Join(root, "notes")
301		entries, err := os.ReadDir(dir)
302		if err != nil {
303			if errors.Is(err, os.ErrNotExist) {
304				return nil, nil
305			}
306			return nil, fmt.Errorf("读取记忆笔记目录失败: %w", err)
307		}
308		notes := make([]Note, 0, len(entries))
309		for _, entry := range entries {
310			if entry.IsDir() || filepath.Ext(entry.Name()) != ".md" {
311				continue
312			}
313			id := strings.TrimSuffix(entry.Name(), ".md")
314			if !sessionIDPattern.MatchString(id) {
315				continue
316			}
317			note, err := s.readNote(scope, id)
318			if err != nil {
319				continue
320			}
321			notes = append(notes, note)
322		}
323		return notes, nil
324	}
