462	func normalizeMemoryText(value string) string {
463		return strings.Join(strings.Fields(strings.ReplaceAll(value, "\r\n", "\n")), " ")
464	}
465	
466	func indexText(value string) string {
467		value = normalizeMemoryText(value)
468		value = strings.ReplaceAll(value, "[", "\\[")
469		return strings.ReplaceAll(value, "]", "\\]")
470	}
