62	// BuildPayload creates stable and dynamic prompt content for one model request.
63	func (r *Runtime) BuildPayload(ctx RequestContext) Payload {
64		payload := Payload{StableSystem: r.StableSystem()}
65		payload.Reminders = append(payload.Reminders, buildEnvironmentReminder(ctx))
66		if reminder, ok := buildContentReminder(ReminderInstructions, "Project instructions", ctx.Session.Instructions); ok {
67			payload.Reminders = append(payload.Reminders, reminder)
68		}
69		if reminder, ok := buildContentReminder(ReminderMemoryIndex, "Durable memory index", ctx.Session.MemoryIndex); ok {
70			payload.Reminders = append(payload.Reminders, reminder)
71		}
72		if ctx.Iteration <= 1 {
73			if reminder, ok := buildContentReminder(ReminderResumeGap, "Resumed session notice", ctx.Session.ResumeGap); ok {
74				payload.Reminders = append(payload.Reminders, reminder)
75			}
76		}
77		if ctx.Mode == "plan" {
78			payload.Reminders = append(payload.Reminders, buildPlanModeReminder(ctx))
79		}
80		return payload
81	}
